	TViewServer();			virtual ~TViewServer();		// Sets the global gViewServer to NULL. 	//------------------------------------------------------------------------------------	// Procedural View Creation	//------------------------------------------------------------------------------------	virtual TWindow* NewPaletteWindow(ResNumber itsRsrcID,									 bool wantHScrollBar,									 bool wantVScrollBar,									 TView* itsMainView,									 TView* itsPaletteView,									 short sizePalette,									 VHSelect whichWay);		// Used for creating MacDraw-like windows with 1 non-scrolling palette along the		// left edge (whichWay = h), or a non-scrolling status area at the top of the window		// (whichWay = v), and a main view that may or may not scroll. Signals Failure if the		// window could not be created.		virtual TWindow* NewSimpleWindow(ResNumber itsRsrcID,									bool wantHScrollBar,									bool wantVScrollBar,									TView* itsView);		// Used for creating simple windows that contain 1 view and may or may not scroll.		// Signals Failure if the window could not be created.		virtual void AddSubViewWithScroller(TWindow* aWindow,												TView* itsView,												bool wantHScrollBar,												bool wantVScrollBar,												const CViewPoint& itsLocation);		// Used to add a view to a window, creating a scroller if needed.	virtual TWindow* NewTWindow(ResNumber itsRsrcID);		// Used for creating a window object. Used within NewPaletteWindow &		// NewSimpleWindow. SIgnals Failure if the window could not be created.		//------------------------------------------------------------------------------------	// Creating Views from View Template	//------------------------------------------------------------------------------------	virtual TWindow* NewTemplateWindow(ResNumber viewRsrcID, TDocument* itsDocument);		// Used for creating a window using a 'view' template.	virtual TView* DoCreateViews(TDocument* itsDocument,										TView* parentView,										ResNumber itsRsrcID,										const CViewPoint& subViewOffset);		// Creates the view hierarchy using ReadViewsFromResource, and calls the root view's		// AdjustSize and HandlePostCreate methods	virtual TView* ReadViewsFromResource(TDocument* itsDocument,											  TView* parentView,											  ResNumber itsRsrcID,											  const CViewPoint& subViewOffset);		// This is the method responsible for creating view hierarchies from resource        // templates. 		// ??? should we have a ReadViewsFromHandle	virtual TView* ReadViewsFrom(CStream_AC* itsStream,										TView* parentView,										const CViewPoint& subviewOffset);		// Called from ReadViewsFromResource		//------------------------------------------------------------------------------------	// Writing Views	//------------------------------------------------------------------------------------	virtual void WriteViewsToResource(TView* view,											 ResNumber itsRsrcID,											 const CStr255_AC& name,											 short resourceAttributes);		// Calls WriteViewsToHandle to write the view to a handle, and adds the handle to		// the current resource fork as a 'View' resource with the given resource id, name,		// and resource attributes.	virtual Handle WriteViewsToHandle(TView* view);		// Creates a stream and calls WriteViewsTo to write out the view to the stream.		// Returns the handle containing the streamed views, suitable for saving as a resource.	//------------------------------------------------------------------------------------	// View Stream Management	//------------------------------------------------------------------------------------	virtual CStream_AC* DoMakeViewStream(ResNumber itsRsrcID, Handle itsHandle);		// creates and returns a TStream to be used when reading or writing views		// if itsHandle != NULL, uses this to create the handle		// else if itsRsrcID != kNoResourceID, uses this to retrieve the resource	//------------------------------------------------------------------------------------	// Member data	//------------------------------------------------------------------------------------public:	static CAutoPtr_AC<TViewServer> fgViewServer;				// the globally accessible view server};//•••  remove after replacing in all examples: #define gViewServer						TViewServer::fgViewServer#endif // __UVIEWSERVER__/*	Historical Change Record:		----- R13 -----		06/05/97	EXPORT_AC, EXPORT_MA, no-load fixes, Memory_AC, Windows_AC, no CW11orLATER, removed segmentation, etc...		04/28/97	Added new view resource version.		04/23/97	Remove Clone declarations from classes we don't clone.		04/14/97	Update for real xxx_cast operators.		03/25/97	AC_ to _AC Name change.		03/21/97	Migrated to CViewRect, CViewPoint, ViewCoordinate.		03/07/97	Massive Changes: Use Exceptions_AC, new to TH_new, use Blah_AC,							Update Copyright, Moved Obsolete APIs into Compatibility.h, etc..		02/18/97	Removed unused itsDocument parameter to NewTWindow, NewPaletteWindow, NewSimpleWindow		08/10/96	Fixed -noload compiles, made more datamembers auto_ptrs, FreeIfObject->delete		08/07/96	Goodbye TObject!		07/15/96	Boolean->bool		----- R11 -----		06/26/96	Install release marker.  Scope many globals.  Change TRUE/FALSE/NULL.		06/25/96	[1345531] Added fwd ref to TStream for noload builds.		----- R10 -----		----- 3.3b1 -----		  7/5/95	Cosmetic. 		 3/13/95	Change Free methods to destructors. 		02/22/95	1184041 Change nil to NULL*/